public void process(METUpdateOrderProcessingStatusContract _contract)
{
    Query       query       = new Query(SysOperationHelper::base64Decode(_contract.parmPackedQuery()));
    QueryRun    queryRun    = new QueryRun(query);

    METSalesOrderProcessingStatus   fromPocessingStatus     = _contract.parmFromOrderProcessingStatus();
    METSalesOrderProcessingStatus   toPocessingStatus       = _contract.parmToOrderProcessingStatus();

    while (queryRun.next())
    {
        SalesTable  salesTable  = queryRun.get(tableNum(SalesTable));

        METSalesTable metSalesTable;

        ttsbegin;
        select forupdate metSalesTable
            where metSalesTable.SalesTable == salesTable.RecId
            && metSalesTable.OrderProcessingStatus == fromPocessingStatus;

        if (metSalesTable.RecId)
        {
            metSalesTable.OrderProcessingStatus = toPocessingStatus;
        }
        metSalesTable.update();
        ttscommit;
    }

}
